const data = $input.first().json;
const btcPrice = parseFloat(data.bitcoin.usd);
const ethPrice = parseFloat(data.ethereum.usd);
const btcChange = parseFloat(data.bitcoin.usd_24h_change);
const ethChange = parseFloat(data.ethereum.usd_24h_change);
const btcVol = parseFloat(data.bitcoin.usd_24h_vol);
const ethVol = parseFloat(data.ethereum.usd_24h_vol);
const btcHolding = 0.5;
const ethHolding = 3;
const btcValue = btcHolding * btcPrice;
const ethValue = ethHolding * ethPrice;
const totalValue = btcValue + ethValue;
const btcWeight = btcValue / totalValue;
const ethWeight = ethValue / totalValue;
const weightedChange = (btcWeight * btcChange) + (ethWeight * ethChange);
const alertStatus = (weightedChange > 0.1 || weightedChange < -0.1) ? 'TRIGGERED' : 'NORMAL';
return [{
  json: {
    btcPrice: parseFloat(btcPrice.toFixed(2)),
    ethPrice: parseFloat(ethPrice.toFixed(2)),
    btcChange: parseFloat(btcChange.toFixed(4)),
    ethChange: parseFloat(ethChange.toFixed(4)),
    btcVolume: parseFloat(btcVol.toFixed(2)),
    ethVolume: parseFloat(ethVol.toFixed(2)),
    btcHolding,
    ethHolding,
    btcValue: parseFloat(btcValue.toFixed(2)),
    ethValue: parseFloat(ethValue.toFixed(2)),
    totalPortfolioValue: parseFloat(totalValue.toFixed(2)),
    weightedDailyChange: parseFloat(weightedChange.toFixed(4)),
    alertStatus
  }
}];

